def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter

    counts = Counter(v for row in grid for v in row)
    bg = counts.most_common(1)[0][0]

    # Find the full row or column containing the divider color 2.
    line = None
    axis = None
    for r in range(h):
        if all(grid[r][c] == 2 for c in range(w)):
            axis, line = 0, r
            break
    if line is None:
        for c in range(w):
            if all(grid[r][c] == 2 for r in range(h)):
                axis, line = 1, c
                break

    out = [row[:] for row in grid]
    if line is None:
        return out

    points = [(r, c, grid[r][c])
              for r in range(h) for c in range(w)
              if grid[r][c] != bg and grid[r][c] != 2]
    if not points:
        return out

    coords = [p[axis] for p in points]
    lo, hi = min(coords), max(coords)

    # Move the pattern toward the divider until its nearest edge touches it.
    if hi < line:
        delta = (line - 1) - hi
        stripe = lo + delta - 1
    elif lo > line:
        delta = (line + 1) - lo
        stripe = hi + delta + 1
    else:
        return out

    for r, c, _ in points:
        out[r][c] = bg
    for r, c, color in points:
        if axis == 0:
            r += delta
        else:
            c += delta
        if 0 <= r < h and 0 <= c < w:
            out[r][c] = color

    if axis == 0 and 0 <= stripe < h:
        out[stripe] = [8] * w
    elif axis == 1 and 0 <= stripe < w:
        for r in range(h):
            out[r][stripe] = 8

    return out
